// Materializer: packages/contract templates for the Go-microservices
// shape 4 (issue #15).
//
// In the polyglot shapes (3 & 4) packages/contract is the ONLY shared
// package (decision 9). Go is the canonical side (decision 19) — but
// shape 4 has TWO Go services, so the committed spec is generated in
// three committed steps, all tripwired:
//
//   openapi.api.yaml   — generated by apps/api's specgen (the main
//                        api's routes: /items). Tripwire:
//                        apps/api/contract_test.go == live spec.
//   openapi.auth.yaml  — generated by apps/api-auth's specgen (the
//                        auth service's routes: /auth/* + JWKS).
//                        Tripwire: apps/api-auth/contract_test.go.
//   openapi.yaml       — the MERGED spec: what TS/Dart clients are
//                        generated from (the spine, decision 9).
//                        Generated by scripts/merge-openapi.mjs from
//                        the two partials. Tripwire:
//                        test/generated.test.ts re-runs the merge.
//
// A spec change therefore flows Go structs -> each service's specgen
// -> merge -> client generation, all via `task contract:generate`,
// and is committed as one diff — clients can only pick it up after
// that regeneration (the Go-as-canonical rule, decision 19).
//
// Per issue #27 the materializer is split by workspace; this module
// owns every file written into packages/contract for shape 4.
// Templates shared with the Go-monolith (package.json, tsconfig, the
// TS client generator, the Dart client) are imported from
// go-contract.js; only the shape-4-specific files live here.

import { join } from 'node:path';
import { type ProjectContext, writeFileRecursive } from './_shared.js';
import {
  clientTs,
  contractPackageJson,
  contractTsconfigJson,
  dartClient,
  dartPubspec,
  generateTsClientMjs,
} from './go-contract.js';

export async function writeGoContractMs(ctx: ProjectContext): Promise<void> {
  const { targetDir } = ctx;

  await writeFileRecursive(join(targetDir, 'packages/contract/openapi.api.yaml'), openapiApiYaml());
  await writeFileRecursive(join(targetDir, 'packages/contract/openapi.auth.yaml'), openapiAuthYaml());
  await writeFileRecursive(join(targetDir, 'packages/contract/openapi.yaml'), openapiMergedYaml());
  await writeFileRecursive(join(targetDir, 'packages/contract/package.json'), contractPackageJson());
  await writeFileRecursive(join(targetDir, 'packages/contract/tsconfig.json'), contractTsconfigJson());
  await writeFileRecursive(join(targetDir, 'packages/contract/README.md'), contractReadmeMs());
  await writeFileRecursive(join(targetDir, 'packages/contract/scripts/merge-openapi.mjs'), mergeOpenapiMjs());
  await writeFileRecursive(join(targetDir, 'packages/contract/scripts/generate-ts-client.mjs'), generateTsClientMjs());
  await writeFileRecursive(join(targetDir, 'packages/contract/src/types.ts'), clientTypesTsMs());
  await writeFileRecursive(join(targetDir, 'packages/contract/src/client.ts'), clientTs());
  await writeFileRecursive(join(targetDir, 'packages/contract/src/index.ts'), clientIndexTsMs());
  await writeFileRecursive(join(targetDir, 'packages/contract/test/generated.test.ts'), generatedTestTsMs());
  await writeFileRecursive(join(targetDir, 'packages/contract/clients/dart/pubspec.yaml'), dartPubspec());
  await writeFileRecursive(join(targetDir, 'packages/contract/clients/dart/lib/openapi_client.dart'), dartClient());
}

function openapiApiYaml(): string {
  return `components:
    schemas:
        ErrorDetail:
            additionalProperties: false
            properties:
                location:
                    description: Where the error occurred, e.g. 'body.items[3].tags' or 'path.thing-id'
                    type: string
                message:
                    description: Error message text
                    type: string
                value:
                    description: The value at the given location
            type: object
        ErrorModel:
            additionalProperties: false
            properties:
                $schema:
                    description: A URL to the JSON Schema for this object.
                    examples:
                        - https://example.com/schemas/ErrorModel.json
                    format: uri
                    readOnly: true
                    type: string
                detail:
                    description: A human-readable explanation specific to this occurrence of the problem.
                    examples:
                        - Property foo is required but is missing.
                    type: string
                errors:
                    description: Optional list of individual error details
                    items:
                        $ref: '#/components/schemas/ErrorDetail'
                    type:
                        - array
                        - "null"
                instance:
                    description: A URI reference that identifies the specific occurrence of the problem.
                    examples:
                        - https://example.com/error-log/abc123
                    format: uri
                    type: string
                status:
                    description: HTTP status code
                    examples:
                        - 400
                    format: int64
                    type: integer
                title:
                    description: A short, human-readable summary of the problem type. This value should not change between occurrences of the error.
                    examples:
                        - Bad Request
                    type: string
                type:
                    default: about:blank
                    description: A URI reference to human-readable documentation for the error.
                    examples:
                        - https://example.com/errors/example
                    format: uri
                    type: string
            type: object
        Item:
            additionalProperties: false
            properties:
                $schema:
                    description: A URL to the JSON Schema for this object.
                    examples:
                        - https://example.com/schemas/Item.json
                    format: uri
                    readOnly: true
                    type: string
                created_at:
                    format: date-time
                    type: string
                id:
                    type: string
                name:
                    maxLength: 200
                    type: string
            required:
                - id
                - name
                - created_at
            type: object
        ItemCreateInputBody:
            additionalProperties: false
            properties:
                $schema:
                    description: A URL to the JSON Schema for this object.
                    examples:
                        - https://example.com/schemas/ItemCreateInputBody.json
                    format: uri
                    readOnly: true
                    type: string
                name:
                    description: Name of the item
                    maxLength: 200
                    minLength: 1
                    type: string
            required:
                - name
            type: object
    securitySchemes:
        bearerAuth:
            bearerFormat: JWT
            description: A short-lived access token (decision 16), minted by apps/api-auth (the sole minter, decision 11); verified locally against its fetched-and-cached JWKS.
            scheme: bearer
            type: http
info:
    description: 'The scaffolded Go api: items demo behind a JWKS-verified Bearer gate (decision 13/11). Auth lives on apps/api-auth (the sole minter).'
    title: Starter API
    version: 0.1.0
openapi: 3.1.0
paths:
    /items:
        get:
            responses:
                "200":
                    content:
                        application/json:
                            schema:
                                items:
                                    $ref: '#/components/schemas/Item'
                                type:
                                    - array
                                    - "null"
                    description: OK
                default:
                    content:
                        application/problem+json:
                            schema:
                                $ref: '#/components/schemas/ErrorModel'
                    description: Error
            security:
                - bearerAuth: []
            summary: List items
            tags:
                - items
        post:
            requestBody:
                content:
                    application/json:
                        schema:
                            $ref: '#/components/schemas/ItemCreateInputBody'
                required: true
            responses:
                "200":
                    content:
                        application/json:
                            schema:
                                $ref: '#/components/schemas/Item'
                    description: OK
                default:
                    content:
                        application/problem+json:
                            schema:
                                $ref: '#/components/schemas/ErrorModel'
                    description: Error
            security:
                - bearerAuth: []
            summary: Create an item
            tags:
                - items
`;
}

